    while(true){
        int n, m; cin >> n >> m;
        if(n == 0 and m == 0) break;

        UnionFind uf(n);
        rep(i, m){
            int a, b; cin >> a >> b; a--, b--;
            uf.unionSet(a, b);
        }

        int num = 0;
        rep(i, n){
            if(uf.root(i) == i){
                num++;
            }
        }

        ll res = 1LL;
        rep(i, num){
            res = MUL(res, 2LL, mod);
        }
        if(num < n){
            res = ADD(res, 1LL, mod);
        }

        cout << res << endl;
    }

    return 0;
}

