#!/usr/bin/python3

import os
import sys


def main():
    N = read_int()
    V = read_ints()
    print(solve(N, V))


def solve(N, V):
    V.sort()
    pos = {}
    for i, a in enumerate(V):
        pos[a] = i
    best = 2
    done = [[False] * N for _ in range(N)]
    for i in range(N):
        a = V[i]
        for j in range(i + 1, N):
            if done[i][j]:
                continue
            b = V[j]
            d = b - a
            c = 2
            done[i][j] = True
            k = j
            v = b + d
            while v in pos:
                done[k][pos[v]] = True
                k = pos[v]
                c += 1
