				dp[i][k] = 1;
			}else{

				dp[i][k] = 2;
			}
		}
	}

	for(int i = 0; i < N; i++){

		scanf("%d",&table[i]);
	}
	sort(table,table+N);

	int ans = 2;
	int diff,right;

	for(int mid = 1; mid <= N-2; mid++){
