				int x = val[k][i];
				if (s[k][i] == x) {
					vector<int> p;
					bool ok = false;
					rep(j, n) {
						if (d[i][j] == -1) p.push_back(j);
						if (d[i][j] == x) ok = true;
					}
					if (ok) continue;
					if (p.size() == 0) return false;
					if (p.size() == 1) {
						d[i][p[0]] = x;
					}
				}
			}
			flip();
		}
	}

	vector<int> is, js;
	rep(i, n) {
		bool filled = true;
		rep(j, n) if (d[i][j] == -1) filled = false;
		if (!filled) is.push_back(i);
	}
	rep(j, n) {
		bool filled = true;
		rep(i, n) if (d[i][j] == -1) filled = false;
		if (!filled) js.push_back(j);
	}
	rep(i, is.size())rep(j, js.size()) {
		d[is[i]][js[j]] = (i + j) % 2;
	}
	return true;
}

