# 二次元累積和
class Ruiwa():
    def __init__(self, a):
        self.H = h = len(a)
        self.W = w = len(a[0])
        self.R = r = a
        for i in range(h):
            for j in range(1,w):
                r[i][j] += r[i][j-1]

        for i in range(1,h):
            for j in range(w):
                r[i][j] += r[i-1][j]

    def search(self, x1, y1, x2, y2):
        if x1 > x2 or y1 > y2:
            return 0

        r = self.R
        rr = r[y2][x2]
        if x1 > 0 and y1 > 0:
            return rr - r[y1-1][x2] - r[y2][x1-1] + r[y1-1][x1-1]
        if x1 > 0:
            rr -= r[y2][x1-1]
        if y1 > 0:
            rr -= r[y1-1][x2]

        return rr

def main():
    rr = []

    def f(n):
        a = [LI() for _ in range(n)]
        xs = set()
        ys = set()
        for l,t,r,b in a:
            xs.add(l)
            xs.add(r)
            ys.add(t)
            ys.add(b)
        xd = {}
        for x,i in zip(sorted(xs), range(len(xs))):
            xd[x] = i
        yd = {}
        for y,i in zip(sorted(ys), range(len(ys))):
            yd[y] = i
        z = []
        for l,t,r,b in a:
            z.append([xd[l],yd[t],xd[r],yd[b]])
        xx = len(xs) + 3
        yy = len(ys) + 3
        aa = [[0]*xx for _ in range(yy)]
        ii = [2**i for i in range(n)]
        for i in range(n):
            l,t,r,b = map(lambda x: x+1, z[i])
            aa[b][l] += ii[i]
            aa[t][l] -= ii[i]
            aa[b][r] -= ii[i]
            aa[t][r] += ii[i]
        rui = Ruiwa(aa)
        t = rui.R
        def _f(i,j,k):
            if i < 0 or i >= yy or j < 0 or j >= xx:
                return
            if t[i][j] != k:
                return
            t[i][j] = -1
            for di,dj in dd:
