        r = 0
        for i in range(yy):
            for j in range(xx):
                if t[i][j] >= 0:
                    _f(i,j,t[i][j])
                    r += 1
        return r

    while True:
        n = I()
        if n == 0:
            break
        rr.append(f(n))

    return '\n'.join(map(str,rr))


