void up(int cur,int ll,int rr)
{
	sum[cur] = sum[L] + sum[R];
	posl[cur] = min(posl[L], posl[R]);
	mnr[cur] = min(mnr[R], sum[R]+mnr[L]);
}
void init(int cur,int ll,int rr)
{
	if(ll==rr)
	{
		if(buf[ll]=='(')
		{
			sum[cur] = mnr[cur] = -1;
			posl[cur] = M;
		}
		else
		{
			sum[cur] = mnr[cur] = 1;
			posl[cur] = ll;
		}
		return;
	}

	int mid = (ll+rr)/2;
	init(L,ll,mid);
	init(R,mid+1,rr);
	up(cur,ll,rr);
}
void upd(int cur,int ll,int rr,int x,int v)
{
	if(ll==rr)
	{
		sum[cur] = mnr[cur] = v;

		if(v==-1) posl[cur]=M;
		else posl[cur]=ll;
		return;
	}

	int mid = (ll+rr)/2;
	if(x<=mid) upd(L,ll,mid,x,v);
	else upd(R,mid+1,rr,x,v);
	up(cur,ll,rr);
}
int ask(int cur,int ll,int rr,int s)
{
	if(ll==rr)
	{
		if(s!=mnr[cur]) return -1;
		return ll;
	}

	int mid = (ll+rr)/2;

	if(mnr[R] > s)
	{
		int re = ask(L,ll,mid,s-sum[R]);
		if(re!=-1) return re;
		return mid+1;
	}
	return ask(R,mid+1,rr,s);
}

