        for j in range(2):
            positions[i][j][0] -= minx
            positions[i][j][1] -= miny
        positions[i].sort()
    return positions


def normal(positions):
    minx = float("inf")
    miny = float("inf")
    minz = float("inf")
    for i in range(len(positions)):
        if positions[i][0][0] < minx:
            minx = positions[i][0][0]
        if positions[i][1][0] < minx:
