            add_edge(i,i+51,1);
            add_edge(i+51,305,1);
        }
        add_edge(203,254,nc);
        for(int i=255;i<=254+m;i++){
            add_edge(254,i,1);
            add_edge(i,306,1);
        }
        add_edge(305,306,nm);
