	rep(i, n) {
		if (i == s || i == t)continue;
		int d1 = query(s, i);
		int d2 = query(i,t);
		if (d1 + d2 == d) {
			v.push_back({ d1,i });
		}
	}
	sort(v.begin(), v.end());
	vector<int> ans; ans.push_back(s);
	if (v.size() == 0) {
		cout << "! " << s << " " << t << endl; return;
	}
	ans.push_back(v[0].second);
	int cur = 0;
	for (int i = 1; i < v.size(); i++) {
		int dist = query(v[cur].second, v[i].second);
		if (v[i].first - v[cur].first == dist) {
			ans.push_back(v[i].second); cur = i;
		}
	}
	ans.push_back(t);
	cout << "!";
	rep(i, ans.size()) {
		cout << " " << ans[i]+1;
	}
	cout << endl;
}

