const int N = 50;

int h, w, m, co[3][N][N], r, c, pr, pc, t;
char da[N][N];
vector<int> ti[N][N];
int dy[] = {-1, 0, 1, 0};
int dx[] = {0, 1, 0, -1};
bool vis[N][N];

int move(int y, int x, int cnt){
  if(y == r && x == c) return cnt;
  vis[y][x] = true;
  for(int i=0;i<4;i++){
    int ny = y + dy[i];
    int nx = x + dx[i];
    if(ny < 0 || ny >= h || nx < 0 || nx >= w) continue;
    if(da[ny][nx] == '#') continue;
    if(vis[ny][nx]) continue;
    int res = move(ny, nx, cnt+1);
    if(res >= 0){
      ti[y][x].push_back(t + cnt);
      return res;
    }
  }
  return -1;
}

