template <typename T>
struct treap {
	struct node {
		T v;
		int p;
		node *n[2];

		node(T x, T p) {
			v = x;
			this->p = p;
			n[0] = n[1] = nullptr;
		}
	};

	typedef node N;
	N *root = nullptr;

	N* rotate(N* t, int b) {
		N *s = t->n[1 - b];
		t->n[1 - b] = s->n[b];
		s->n[b] = t;
		return s;
	}
	N* insert(T k, int p, N *t) {
		if (!t)
			return new N(k, p);
		int b = !(k < t->v);
		t->n[b] = insert(k, p, t->n[b]);
		return (t->p < t->n[b]->p) ? rotate(t, 1 - b) : t;
	}
	void insert(T k, int p) {
		root = insert(k, p, root);
	}
	N* erace(N *t, T x) {
		if (!t)
			;
		else if (t->v > x)
			t->n[0] = erace(t->n[0], x);
		else if (t->v < x)
			t->n[1] = erace(t->n[1], x);
		else {
			t = erace(!t->n[0] && !t->n[1] ? nullptr :
					  !t->n[0] ? rotate(t, 0) :
					  !t->n[1] ? rotate(t, 1) :
					  rotate(t, t->n[0]->p > t->n[1]->p), x);
		}
		return t;
	}
	void erace(T x) {
		root = erace(root, x);
	}
	bool find(N *t, T x) {
		return !t ? false : t->v > x ? find(t->n[0], x) : t->v < x ? find(t->n[1], x) : true;
	}
	bool find(T x) {
		return find(root, x);
	}
	void print(N *r, v &buf) {
		if (r == nullptr)
			return;
		buf.push_back(r->v);
		print(r->n[0], buf);
		out(' ', r->v);
		print(r->n[1], buf);
	}
	void print() {
		v buf;
		print(root, buf);
		out('\n', buf);
	}
};

