from collections import deque


def solve(tree, root):
    def dfs1():
        """各頂点の部分木内で最も遠い頂点(葉)までの距離を求める"""
        q1 = deque([root])
        q2 = deque([root])
        while q1:
            v = q1.pop()
            for nxt_v, cost in tree[v]:
                if nxt_v in par:
                    continue
                else:
                    par[nxt_v] = v
                    q1.append(nxt_v)
                    q2.append(nxt_v)
        while q2:
            v = q2.pop()
            for nxt_v, cost in tree[v]:
                if nxt_v == par[v]:
                    continue
                else:
                    dist1[v] = max(dist1[v], dist1[nxt_v] + cost)

    def dfs2():
